.faq-answer-inner {
  padding-bottom: 24px;
  color: var(--gray); font-size: 16px; line-height: 1.7;
}

/* ========================================
   Digital Platform
   ======================================== */
.features-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px; margin-top: 40px;
}
.feature-card {
  background: var(--black-card); border: 1px solid var(--gray-border);
  border-radius: 8px; padding: 36px 28px;
  transition: border-color var(--transition), transform var(--transition);
}
.feature-card:hover { border-color: var(--red); transform: translateY(-4px); }
.feature-card .icon {
  width: 56px; height: 56px; border-radius: 12px;
  background: var(--red-subtle); display: flex;
  align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.feature-card .icon svg { width: 28px; height: 28px; stroke: var(--red); }
.feature-card h3 {
  font-family: var(--font-heading); font-size: 20px;
  font-weight: 700; text-transform: uppercase;
  margin-bottom: 12px;
}
.feature-card p { color: var(--gray); line-height: 1.7; font-size: 15px; }

/* ========================================
   CTA Section (Generic)
   ======================================== */
.cta-section {
  text-align: center; padding: 80px 0;
  background: linear-gradient(135deg, var(--red-dark) 0%, var(--red) 100%);
}
.cta-section .section-title { color: var(--white); }
.cta-section .btn { background: var(--white); color: var(--red); }
.cta-section .btn:hover { background: var(--black); color: var(--white); }

/* ========================================
   Responsive
   ======================================== */
@media (max-width: 1023px) {
  .section { padding: 60px 0; }
  .hero { min-height: 70vh; }
}

@media (max-width: 767px) {
  .section { padding: 48px 0; }
  .hero { min-height: 60vh; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; text-align: center; }
  .free-trial { padding: 64px 0; }
  .newsletter-inner { flex-direction: column; align-items: flex-start; }
}

/* ========================================
   Animations (respect prefers-reduced-motion)
   ======================================== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}
