/* ========================================
   RedRoom Fitness — Shared Styles
   ======================================== */

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --red: #E63946;
  --red-dark: #C1121F;
  --red-light: #FF4D5A;
  --red-glow: rgba(230, 57, 70, 0.25);
  --red-subtle: rgba(230, 57, 70, 0.08);
  --black: #141414;
  --black-light: #1C1C1C;
  --black-lighter: #2A2A2A;
  --black-card: #1A1A1A;
  --white: #FFFFFF;
  --gray: #B0B0B0;
  --gray-dark: #777777;
  --gray-border: #333333;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --container: 1200px;
  --transition: 250ms ease;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  font-family: var(--font-body);
  background: var(--black);
  color: var(--white);
  line-height: 1.6;
  font-size: 16px;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* Utility */
.container { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* Skip Link */
.skip-link {
  position: absolute; top: -100%; left: 16px; z-index: 10000;
  background: var(--red); color: var(--white); padding: 12px 24px;
  font-weight: 600; border-radius: 0 0 8px 8px;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ========================================
   Top Promo Bar
   ======================================== */
.top-promo {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  font-family: var(--font-heading);
}
.top-promo a { text-decoration: underline; margin-left: 12px; font-weight: 700; }
.top-promo a:hover { color: var(--black); }

/* ========================================
   Navigation
   ======================================== */
.navbar {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-border);
}
.navbar .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 24px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 2px; color: var(--red);
  display: flex; align-items: center; gap: 4px;
}
.nav-logo span { color: var(--white); }

.nav-links { display: flex; align-items: center; gap: 28px; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 14px; font-weight: 500; text-transform: uppercase;
  letter-spacing: 1px; color: var(--gray);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }
.nav-links a.active::after {
  content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
  height: 2px; background: var(--red);
}

.nav-utility { display: flex; align-items: center; gap: 16px; }
.nav-utility .btn-book {
  background: var(--red); color: var(--white);
  padding: 10px 20px; border-radius: 4px;
  font-family: var(--font-heading); font-size: 13px;
  font-weight: 600; text-transform: uppercase; letter-spacing: 1px;
  transition: background var(--transition), transform 150ms ease;
}
.nav-utility .btn-book:hover { background: var(--red-dark); transform: translateY(-1px); }

.hamburger {
  display: none; flex-direction: column; gap: 5px;
  padding: 8px; cursor: pointer;
}
.hamburger span {
  display: block; width: 24px; height: 2px;
  background: var(--white); transition: var(--transition);
}

/* Mobile Nav */
@media (max-width: 1023px) {
  .nav-links, .nav-utility { display: none; }
  .hamburger { display: flex; }

  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: 72px; left: 0; right: 0;
    background: var(--black); padding: 24px;
    border-bottom: 1px solid var(--gray-border);
    gap: 20px;
  }
  .nav-links.open a { font-size: 16px; color: var(--white); }
  .nav-utility.open {
    display: flex; position: absolute; top: calc(72px + var(--nav-links-height, 200px));
    left: 0; right: 0; background: var(--black);
    padding: 16px 24px 24px; border-bottom: 1px solid var(--gray-border);
  }
}

/* ========================================
   Buttons
   ======================================== */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 14px 32px; border-radius: 4px;
  font-family: var(--font-heading); font-size: 16px;
  font-weight: 600; text-transform: uppercase; letter-spacing: 1.5px;
  transition: all var(--transition); cursor: pointer;
  min-height: 44px;
}
.btn-primary { background: var(--red); color: var(--white); }
.btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); box-shadow: 0 8px 24px var(--red-glow); }
.btn-outline { border: 2px solid var(--white); color: var(--white); background: transparent; }
.btn-outline:hover { background: var(--white); color: var(--black); }
.btn-outline-red { border: 2px solid var(--red); color: var(--red); background: transparent; }
.btn-outline-red:hover { background: var(--red); color: var(--white); }

/* ========================================
   Section Helpers
   ======================================== */
.section { padding: 80px 0; }
.section-dark { background: var(--black-light); }
.section-red { background: var(--red); }

.section-label {
  font-family: var(--font-heading);
  font-size: 13px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 3px; color: var(--red); margin-bottom: 16px;
}
.section-title {
  font-family: var(--font-heading);
  font-size: clamp(32px, 5vw, 56px); font-weight: 700;
  text-transform: uppercase; letter-spacing: 1px;
  line-height: 1.1; margin-bottom: 24px;
}
.section-title span { color: var(--red); }
.section-text {
  font-size: 18px; line-height: 1.7; color: var(--gray);
  max-width: 640px;
}

/* ========================================
   Hero
   ======================================== */
.hero {
  position: relative; min-height: 85vh;
  display: flex; align-items: center;
  background: linear-gradient(135deg, var(--black) 0%, #1a0005 50%, var(--black) 100%);
  overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, var(--red-glow) 0%, transparent 60%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 2; }
.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(40px, 7vw, 80px); font-weight: 700;
  text-transform: uppercase; line-height: 1.05;
  letter-spacing: 2px; margin-bottom: 20px;
}
.hero-title .red { color: var(--red); }
.hero-subtitle {
  font-size: clamp(16px, 2vw, 20px); color: var(--gray);
  line-height: 1.6; max-width: 560px; margin-bottom: 32px;
}
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }

/* ========================================
   Community Promo
   ======================================== */
.community-promo { text-align: center; }
.community-promo .section-text { margin: 0 auto 32px; }

/* ========================================
   Two Ways
   ======================================== */
.two-ways-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 32px; margin-top: 40px;
}
.way-card {
  background: var(--black-card); border: 1px solid var(--gray-border);
  border-radius: 8px; padding: 48px 36px;
  transition: border-color var(--transition), transform var(--transition);
}
.way-card:hover { border-color: var(--red); transform: translateY(-4px); }
.way-card .tag {
  display: inline-block; background: var(--red-subtle); color: var(--red);
  padding: 6px 16px; border-radius: 4px;
  font-family: var(--font-heading); font-size: 13px;
  font-weight: 600; text-transform: uppercase; letter-spacing: 1px;
  margin-bottom: 20px;
}
.way-card h3 {
  font-family: var(--font-heading); font-size: 28px;
  font-weight: 700; text-transform: uppercase;
  margin-bottom: 16px;
}
.way-card p { color: var(--gray); line-height: 1.7; }

@media (max-width: 767px) {
  .two-ways-grid { grid-template-columns: 1fr; }
}

/* ========================================
   Studio Experience
   ======================================== */
.studio-experience {
  position: relative; overflow: hidden;
  background: linear-gradient(180deg, var(--black) 0%, #1a0005 100%);
}
.studio-experience::before {
  content: ''; position: absolute; top: -50%; right: -20%;
  width: 600px; height: 600px;
  background: radial-gradient(circle, var(--red-glow), transparent 70%);
  pointer-events: none;
}

/* ========================================
   Free Trial CTA
   ======================================== */
.free-trial {
  text-align: center; padding: 100px 0;
  background: linear-gradient(135deg, var(--red-dark) 0%, var(--red) 50%, var(--red-light) 100%);
  position: relative; overflow: hidden;
}
.free-trial::before {
  content: ''; position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
  pointer-events: none;
}
.free-trial .section-title { color: var(--white); }
.free-trial .btn { background: var(--white); color: var(--red); font-size: 18px; padding: 18px 48px; }
.free-trial .btn:hover { background: var(--black); color: var(--white); transform: translateY(-2px); box-shadow: 0 12px 32px rgba(0,0,0,0.3); }

/* ========================================
   Carousel
   ======================================== */
.carousel-section { overflow: hidden; }
.carousel-track-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex; transition: transform 500ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%; position: relative;
  aspect-ratio: 16/7; display: flex; align-items: flex-end;
  overflow: hidden;
}
.carousel-slide-bg {
  position: absolute; inset: 0;
  background-size: cover; background-position: center;
}
.carousel-slide-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(0deg, rgba(20,20,20,0.9) 0%, rgba(20,20,20,0.2) 50%, transparent 100%);
}
.carousel-slide-content {
  position: relative; z-index: 2; padding: 40px;
  font-family: var(--font-heading); font-size: 24px;
  font-weight: 600; text-transform: uppercase; letter-spacing: 1px;
}
.carousel-controls {
  display: flex; align-items: center; justify-content: center;
  gap: 16px; margin-top: 24px;
}
.carousel-btn {
  width: 48px; height: 48px; border-radius: 50%;
  border: 2px solid var(--gray-border); color: var(--white);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); background: transparent;
}
.carousel-btn:hover { border-color: var(--red); color: var(--red); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--gray-border); cursor: pointer;
  transition: background var(--transition);
}
.carousel-dot.active { background: var(--red); }

@media (max-width: 767px) {
  .carousel-slide { aspect-ratio: 16/9; }
  .carousel-slide-content { padding: 20px; font-size: 18px; }
}

/* ========================================
   Newsletter
   ======================================== */
.newsletter {
  border-top: 1px solid var(--gray-border);
  padding: 60px 0;
}
.newsletter-inner {
  display: flex; align-items: center; gap: 32px;
  flex-wrap: wrap;
}
.newsletter-text { flex: 1; min-width: 280px; }
.newsletter-text h3 {
  font-family: var(--font-heading); font-size: 24px;
  text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px;
}
.newsletter-text p { color: var(--gray); font-size: 15px; }
.newsletter-form { display: flex; gap: 12px; flex: 1; min-width: 300px; }
.newsletter-input {
  flex: 1; padding: 14px 18px;
  background: var(--black-lighter); border: 1px solid var(--gray-border);
  border-radius: 4px; color: var(--white); font-size: 15px;
  font-family: var(--font-body); min-height: 48px;
  transition: border-color var(--transition);
}
.newsletter-input:focus { outline: none; border-color: var(--red); }
.newsletter-input.error { border-color: #ff4444; }
.newsletter-input.success { border-color: #44ff44; }
.newsletter-msg {
  font-size: 13px; margin-top: 6px;
  min-height: 20px;
}
.newsletter-msg.error { color: #ff4444; }
.newsletter-msg.success { color: #44ff44; }

@media (max-width: 767px) {
  .newsletter-form { flex-direction: column; }
}

/* ========================================
   Footer
   ======================================== */
.footer {
  background: var(--black-light);
  border-top: 1px solid var(--gray-border);
  padding: 60px 0 32px;
}
.footer-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px; margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 16px; }
.footer-brand p { color: var(--gray); font-size: 14px; line-height: 1.7; max-width: 300px; }

.footer-col h4 {
  font-family: var(--font-heading); font-size: 14px;
  text-transform: uppercase; letter-spacing: 2px;
  margin-bottom: 20px; color: var(--white);
}
.footer-col a {
  display: block; color: var(--gray); font-size: 14px;
  padding: 4px 0; transition: color var(--transition);
}
.footer-col a:hover { color: var(--red); }

.country-select {
  margin-top: 16px; position: relative; display: inline-block;
}
.country-select select {
  appearance: none; background: var(--black-lighter);
  border: 1px solid var(--gray-border); color: var(--white);
  padding: 10px 36px 10px 14px; border-radius: 4px;
  font-size: 14px; font-family: var(--font-body);
  cursor: pointer; min-height: 44px;
}
.country-select::after {
  content: '▾'; position: absolute; right: 12px; top: 50%;
  transform: translateY(-50%); color: var(--gray); pointer-events: none;
}

.footer-bottom {
  border-top: 1px solid var(--gray-border);
  padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { color: var(--gray-dark); font-size: 13px; }
.footer-bottom-links { display: flex; gap: 20px; }
.footer-bottom-links a { color: var(--gray-dark); font-size: 13px; transition: color var(--transition); }
.footer-bottom-links a:hover { color: var(--red); }

@media (max-width: 767px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ========================================
   Workout Page — Toggle
   ======================================== */
.toggle-container { margin-top: 40px; }
.toggle-tabs {
  display: inline-flex; background: var(--black-lighter);
  border-radius: 8px; padding: 4px; margin-bottom: 32px;
}
.toggle-tab {
  padding: 14px 32px; border-radius: 6px;
  font-family: var(--font-heading); font-size: 16px;
  font-weight: 600; text-transform: uppercase; letter-spacing: 1px;
  color: var(--gray); transition: all var(--transition);
  cursor: pointer; min-height: 48px;
  display: flex; align-items: center;
}
.toggle-tab.active { background: var(--red); color: var(--white); }
.toggle-tab:hover:not(.active) { color: var(--white); }

.toggle-panel { display: none; }
.toggle-panel.active { display: block; animation: fadeIn 300ms ease; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ========================================
   Workout Page — Schedule Table
   ======================================== */
.schedule-table {
  width: 100%; border-collapse: collapse;
  margin-top: 32px;
}
.schedule-table th {
  font-family: var(--font-heading); font-size: 14px;
  text-transform: uppercase; letter-spacing: 2px;
  text-align: left; padding: 16px 20px;
  border-bottom: 2px solid var(--red);
  color: var(--red);
}
.schedule-table td {
  padding: 16px 20px; border-bottom: 1px solid var(--gray-border);
  font-size: 16px;
}
.schedule-table tr:hover td { background: var(--red-subtle); }
.schedule-table .day {
  font-family: var(--font-heading); font-weight: 600;
  text-transform: uppercase; letter-spacing: 1px;
}

@media (max-width: 767px) {
  .schedule-table th, .schedule-table td { padding: 12px 14px; font-size: 14px; }
}

/* ========================================
   Instructors Page
   ======================================== */
.filter-controls {
  display: flex; align-items: center; gap: 16px;
  margin-bottom: 40px; flex-wrap: wrap;
}
.filter-controls label {
  font-family: var(--font-heading); font-size: 14px;
  text-transform: uppercase; letter-spacing: 1px;
  color: var(--gray);
}
.filter-select {
  appearance: none; background: var(--black-lighter);
  border: 1px solid var(--gray-border); color: var(--white);
