    hamburger.addEventListener('click', () => {
      const open = navLinks.classList.toggle('open');
      hamburger.setAttribute('aria-expanded', open);
    });

    // Carousel
    const track = document.getElementById('carouselTrack');
    const dots = document.querySelectorAll('.carousel-dot');
    let currentSlide = 0;
    const totalSlides = 4;

    function goToSlide(index) {
      currentSlide = ((index % totalSlides) + totalSlides) % totalSlides;
      track.style.transform = 'translateX(-' + (currentSlide * 100) + '%)';
      dots.forEach((d, i) => d.classList.toggle('active', i === currentSlide));
    }

    document.getElementById('carouselPrev').addEventListener('click', () => goToSlide(currentSlide - 1));
    document.getElementById('carouselNext').addEventListener('click', () => goToSlide(currentSlide + 1));
    dots.forEach(dot => dot.addEventListener('click', () => goToSlide(parseInt(dot.dataset.index))));

    // Touch/swipe support
    let touchStartX = 0;
    let touchEndX = 0;
    track.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; }, { passive: true });
    track.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      const diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 50) {
        if (diff > 0) goToSlide(currentSlide + 1);
        else goToSlide(currentSlide - 1);
      }
    }, { passive: true });

    // Auto-advance every 6s
    let autoPlay = setInterval(() => goToSlide(currentSlide + 1), 6000);
    track.addEventListener('pointerenter', () => clearInterval(autoPlay));
    track.addEventListener('pointerleave', () => { autoPlay = setInterval(() => goToSlide(currentSlide + 1), 6000); });

    // Newsletter validation
    const form = document.getElementById('newsletterForm');
    const emailInput = document.getElementById('emailInput');
    const emailMsg = document.getElementById('emailMsg');
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    form.addEventListener('submit', e => {
      e.preventDefault();
      const val = emailInput.value.trim();
      emailInput.classList.remove('error', 'success');
      emailMsg.classList.remove('error', 'success');
      emailMsg.textContent = '';

      if (!val) {
        emailInput.classList.add('error');
        emailMsg.classList.add('error');
        emailMsg.textContent = 'Please enter your email address.';
        emailInput.focus();
        return;
      }
      if (!emailRegex.test(val)) {
        emailInput.classList.add('error');
        emailMsg.classList.add('error');
        emailMsg.textContent = 'Please enter a valid email address.';
        emailInput.focus();
        return;
      }
      emailInput.classList.add('success');
      emailMsg.classList.add('success');
      emailMsg.textContent = 'You\'re in! Check your inbox for confirmation.';
      emailInput.value = '';
    });

    emailInput.addEventListener('input', () => {
      emailInput.classList.remove('error', 'success');
      emailMsg.classList.remove('error', 'success');
      emailMsg.textContent = '';
    });
  </script>
