      this.setAttribute('aria-expanded', open);
    });

    // Newsletter
    const form = document.getElementById('newsletterForm');
    const emailInput = document.getElementById('emailInput');
    const emailMsg = document.getElementById('emailMsg');
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    form.addEventListener('submit', e => {
      e.preventDefault();
      const val = emailInput.value.trim();
      emailInput.classList.remove('error', 'success');
      emailMsg.classList.remove('error', 'success');
      emailMsg.textContent = '';
      if (!val) {
        emailInput.classList.add('error'); emailMsg.classList.add('error');
        emailMsg.textContent = 'Please enter your email address.'; emailInput.focus(); return;
      }
      if (!emailRegex.test(val)) {
        emailInput.classList.add('error'); emailMsg.classList.add('error');
        emailMsg.textContent = 'Please enter a valid email address.'; emailInput.focus(); return;
      }
      emailInput.classList.add('success'); emailMsg.classList.add('success');
      emailMsg.textContent = "You're in! Check your inbox for confirmation.";
      emailInput.value = '';
    });
